#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <ctype.h>

#define MAX_HEADERS 64
#define MAX_BODY 4096
#define MAX_KEY 128
#define MAX_VAL 512
#define MAX_PROPS 32

typedef struct {
    char key[MAX_KEY];
    char value[MAX_VAL];
} Property;

typedef struct {
    Property props[MAX_PROPS];
    int count;
    Property *parent;  /* prototype chain pointer */
    int parent_count;
} ObjectStore;

static Property global_defaults[] = {
    {"role", "user"},
    {"log_level", "info"},
    {"audit_enabled", "true"},
    {"max_retries", "3"}
};
static int global_defaults_count = 4;

void init_object(ObjectStore *obj) {
    obj->count = 0;
    obj->parent = global_defaults;
    obj->parent_count = global_defaults_count;
}

const char* object_get(ObjectStore *obj, const char *key) {
    for (int i = 0; i < obj->count; i++) {
        if (strcmp(obj->props[i].key, key) == 0)
            return obj->props[i].value;
    }
    /* Walk prototype chain */
    for (int i = 0; i < obj->parent_count; i++) {
        if (strcmp(obj->parent[i].key, key) == 0)
            return obj->parent[i].value;
    }
    return NULL;
}

int object_set(ObjectStore *obj, const char *key, const char *value) {
    /* Check if key uses prototype accessor syntax __proto__.X */
    if (strncmp(key, "__proto__.", 10) == 0) {
        const char *proto_key = key + 10;
        /* Resolve: write into the prototype (parent) chain directly */
        for (int i = 0; i < obj->parent_count; i++) {
            if (strcmp(obj->parent[i].key, proto_key) == 0) {
                strncpy(obj->parent[i].value, value, MAX_VAL - 1);
                obj->parent[i].value[MAX_VAL - 1] = '\0';
                return 1;
            }
        }
        /* Add new property to parent if space */
        if (obj->parent_count < MAX_PROPS) {
            strncpy(obj->parent[obj->parent_count].key, proto_key, MAX_KEY - 1);
            strncpy(obj->parent[obj->parent_count].value, value, MAX_VAL - 1);
            obj->parent_count++;
            global_defaults_count = obj->parent_count;
            return 1;
        }
        return 0;
    }
    /* Normal set on own properties */
    for (int i = 0; i < obj->count; i++) {
        if (strcmp(obj->props[i].key, key) == 0) {
            strncpy(obj->props[i].value, value, MAX_VAL - 1);
            obj->props[i].value[MAX_VAL - 1] = '\0';
            return 1;
        }
    }
    if (obj->count < MAX_PROPS) {
        strncpy(obj->props[obj->count].key, key, MAX_KEY - 1);
        strncpy(obj->props[obj->count].value, value, MAX_VAL - 1);
        obj->count++;
        return 1;
    }
    return 0;
}

void audit_log(ObjectStore *session, const char *action) {
    const char *enabled = object_get(session, "audit_enabled");
    if (enabled && strcmp(enabled, "true") == 0) {
        const char *role = object_get(session, "role");
        fprintf(stderr, "[AUDIT] role=%s action=%s\n", role ? role : "unknown", action);
    }
}

int parse_json_body(const char *body, ObjectStore *obj) {
    /* Minimal JSON-like parser: {"key":"val", ...} */
    const char *p = body;
    while (*p && *p != '{') p++;
    if (!*p) return 0;
    p++;
    while (*p) {
        while (*p && (isspace(*p) || *p == ',')) p++;
        if (*p == '}') break;
        if (*p != '"') return -1;
        p++;
        char key[MAX_KEY] = {0};
        int ki = 0;
        while (*p && *p != '"' && ki < MAX_KEY - 1) key[ki++] = *p++;
        if (*p == '"') p++;
        while (*p && *p != ':') p++;
        if (*p == ':') p++;
        while (*p && isspace(*p)) p++;
        if (*p != '"') return -1;
        p++;
        char val[MAX_VAL] = {0};
        int vi = 0;
        while (*p && *p != '"' && vi < MAX_VAL - 1) val[vi++] = *p++;
        if (*p == '"') p++;
        object_set(obj, key, val);
    }
    return 0;
}

void handle_request(int client_fd) {
    char buf[MAX_BODY];
    int n = read(client_fd, buf, sizeof(buf) - 1);
    if (n <= 0) { close(client_fd); return; }
    buf[n] = '\0';

    ObjectStore session;
    init_object(&session);

    /* Find body after headers */
    char *body = strstr(buf, "\r\n\r\n");
    if (body) {
        body += 4;
        parse_json_body(body, &session);
    }

    audit_log(&session, "api_request");

    const char *role = object_get(&session, "role");
    char response[512];
    if (role && strcmp(role, "admin") == 0) {
        snprintf(response, sizeof(response),
            "HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\n\r\nAdmin access granted\n");
    } else {
        snprintf(response, sizeof(response),
            "HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\n\r\nUser access: role=%s\n",
            role ? role : "user");
    }
    write(client_fd, response, strlen(response));
    close(client_fd);
}

int main(int argc, char *argv[]) {
    int port = 8080;
    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    struct sockaddr_in addr = {0};
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(port);
    bind(server_fd, (struct sockaddr*)&addr, sizeof(addr));
    listen(server_fd, 10);

    fprintf(stderr, "Server listening on port %d\n", port);
    while (1) {
        int client_fd = accept(server_fd, NULL, NULL);
        if (client_fd >= 0) handle_request(client_fd);
    }
    return 0;
}
